"""Original vector128 partial-output write width; no change to reader math."""
import hashlib
from pathlib import Path
import re
from triton.language import core

IDENTITY=hashlib.sha256(Path(__file__).read_bytes()).hexdigest()


@core.builtin
def output_packet_group(partial,maxima,sums,query,head,splits,split,row,kg,mx,norm,a0_0,a0_1,a0_2,a0_3,a1_0,a1_1,a1_2,a1_3,a2_0,a2_1,a2_2,a2_3,a3_0,a3_1,a3_2,a3_3,a4_0,a4_1,a4_2,a4_3,a5_0,a5_1,a5_2,a5_3,a6_0,a6_1,a6_2,a6_3,a7_0,a7_1,a7_2,a7_3,_builder=None):
    args=[core._to_tensor(v,_builder) for v in (partial,maxima,sums,query,head,splits,split,row,kg,mx,norm,a0_0,a0_1,a0_2,a0_3,a1_0,a1_1,a1_2,a1_3,a2_0,a2_1,a2_2,a2_3,a3_0,a3_1,a3_2,a3_3,a4_0,a4_1,a4_2,a4_3,a5_0,a5_1,a5_2,a5_3,a6_0,a6_1,a6_2,a6_3,a7_0,a7_1,a7_2,a7_3)]
    for i in range(3,9):
        args[i]=args[i].to(core.int32,_builder=_builder)
    dtype=args[9].type
    return core.tensor(_builder.create_extern_elementwise('','','__reader_output_packet_group',
        [v.handle for v in args],dtype.to_ir(_builder),False),dtype)


def lower_output(module):
    module,n=re.subn(r'(?m)^declare[^\n]*@__reader_output_packet_group\([^\n]*\)[^\n]*$','',module)
    assert n==1
    return module+'\n'+'define internal float @__reader_output_packet_group(ptr addrspace(1) %partial,ptr addrspace(1) %maxima,ptr addrspace(1) %sums,i32 %query,i32 %head,i32 %splits,i32 %split,i32 %row,i32 %kg,float %mx,float %norm,float %a0_0,float %a0_1,float %a0_2,float %a0_3,float %a1_0,float %a1_1,float %a1_2,float %a1_3,float %a2_0,float %a2_1,float %a2_2,float %a2_3,float %a3_0,float %a3_1,float %a3_2,float %a3_3,float %a4_0,float %a4_1,float %a4_2,float %a4_3,float %a5_0,float %a5_1,float %a5_2,float %a5_3,float %a6_0,float %a6_1,float %a6_2,float %a6_3,float %a7_0,float %a7_1,float %a7_2,float %a7_3) alwaysinline nounwind convergent {\nentry:\n  %active = icmp ult i32 %row,8\n  br i1 %active,label %write,label %done\nwrite:\n  %q = sext i32 %query to i64\n  %h = sext i32 %head to i64\n  %count = sext i32 %splits to i64\n  %shard = sext i32 %split to i64\n  %qh0 = shl i64 %q,1\n  %qh = add i64 %qh0,%h\n  %split0 = mul i64 %qh,%count\n  %split1 = add i64 %split0,%shard\n  %base0 = shl i64 %split1,3\n  %row0 = and i32 %row,7\n  %row1 = zext i32 %row0 to i64\n  %base = or i64 %base0,%row1\n  %off0 = shl i64 %base,7\n  %kg0 = zext i32 %kg to i64\n  %off1 = shl i64 %kg0,2\n  %off = add i64 %off0,%off1\n  %p = getelementptr float,ptr addrspace(1) %partial,i64 %off\n  %v0_0 = insertelement <4 x float> poison,float %a0_0,i32 0\n  %v0_1 = insertelement <4 x float> %v0_0,float %a0_1,i32 1\n  %v0_2 = insertelement <4 x float> %v0_1,float %a0_2,i32 2\n  %v0_3 = insertelement <4 x float> %v0_2,float %a0_3,i32 3\n  store <4 x float> %v0_3,ptr addrspace(1) %p,align 16\n  %p1 = getelementptr float,ptr addrspace(1) %p,i64 16\n  %v1_0 = insertelement <4 x float> poison,float %a1_0,i32 0\n  %v1_1 = insertelement <4 x float> %v1_0,float %a1_1,i32 1\n  %v1_2 = insertelement <4 x float> %v1_1,float %a1_2,i32 2\n  %v1_3 = insertelement <4 x float> %v1_2,float %a1_3,i32 3\n  store <4 x float> %v1_3,ptr addrspace(1) %p1,align 16\n  %p2 = getelementptr float,ptr addrspace(1) %p,i64 32\n  %v2_0 = insertelement <4 x float> poison,float %a2_0,i32 0\n  %v2_1 = insertelement <4 x float> %v2_0,float %a2_1,i32 1\n  %v2_2 = insertelement <4 x float> %v2_1,float %a2_2,i32 2\n  %v2_3 = insertelement <4 x float> %v2_2,float %a2_3,i32 3\n  store <4 x float> %v2_3,ptr addrspace(1) %p2,align 16\n  %p3 = getelementptr float,ptr addrspace(1) %p,i64 48\n  %v3_0 = insertelement <4 x float> poison,float %a3_0,i32 0\n  %v3_1 = insertelement <4 x float> %v3_0,float %a3_1,i32 1\n  %v3_2 = insertelement <4 x float> %v3_1,float %a3_2,i32 2\n  %v3_3 = insertelement <4 x float> %v3_2,float %a3_3,i32 3\n  store <4 x float> %v3_3,ptr addrspace(1) %p3,align 16\n  %p4 = getelementptr float,ptr addrspace(1) %p,i64 64\n  %v4_0 = insertelement <4 x float> poison,float %a4_0,i32 0\n  %v4_1 = insertelement <4 x float> %v4_0,float %a4_1,i32 1\n  %v4_2 = insertelement <4 x float> %v4_1,float %a4_2,i32 2\n  %v4_3 = insertelement <4 x float> %v4_2,float %a4_3,i32 3\n  store <4 x float> %v4_3,ptr addrspace(1) %p4,align 16\n  %p5 = getelementptr float,ptr addrspace(1) %p,i64 80\n  %v5_0 = insertelement <4 x float> poison,float %a5_0,i32 0\n  %v5_1 = insertelement <4 x float> %v5_0,float %a5_1,i32 1\n  %v5_2 = insertelement <4 x float> %v5_1,float %a5_2,i32 2\n  %v5_3 = insertelement <4 x float> %v5_2,float %a5_3,i32 3\n  store <4 x float> %v5_3,ptr addrspace(1) %p5,align 16\n  %p6 = getelementptr float,ptr addrspace(1) %p,i64 96\n  %v6_0 = insertelement <4 x float> poison,float %a6_0,i32 0\n  %v6_1 = insertelement <4 x float> %v6_0,float %a6_1,i32 1\n  %v6_2 = insertelement <4 x float> %v6_1,float %a6_2,i32 2\n  %v6_3 = insertelement <4 x float> %v6_2,float %a6_3,i32 3\n  store <4 x float> %v6_3,ptr addrspace(1) %p6,align 16\n  %p7 = getelementptr float,ptr addrspace(1) %p,i64 112\n  %v7_0 = insertelement <4 x float> poison,float %a7_0,i32 0\n  %v7_1 = insertelement <4 x float> %v7_0,float %a7_1,i32 1\n  %v7_2 = insertelement <4 x float> %v7_1,float %a7_2,i32 2\n  %v7_3 = insertelement <4 x float> %v7_2,float %a7_3,i32 3\n  store <4 x float> %v7_3,ptr addrspace(1) %p7,align 16\n  %owns = icmp eq i32 %kg,0\n  br i1 %owns,label %stats,label %done\nstats:\n  %maxout = getelementptr float,ptr addrspace(1) %maxima,i64 %base\n  %sumout = getelementptr float,ptr addrspace(1) %sums,i64 %base\n  store float %mx,ptr addrspace(1) %maxout,align 4\n  store float %norm,ptr addrspace(1) %sumout,align 4\n  br label %done\ndone:\n  ret float %a0_0\n}\n'
